303:     stream.on('error', err => {
304:       if (stream.readable) {
305:         stream.destroy();
306:       }
307:       if (!callback) {
308:         return;
309:       }
310: 
311:       return err.code !== 'ENOENT' ? callback(err) : callback(null, results);
312:     });
313: 
314:     stream.on('data', data => {
315:       data = (buff + data).split(/\n+/);
316:       const l = data.length - 1;
317:       let i = 0;
318: 
319:       for (; i < l; i++) {
320:         if (!options.start || row >= options.start) {
321:           add(data[i]);
322:         }
323:         row++;
324:       }
325: 
326:       buff = data[l];
327:     });
328: 
329:     stream.on('close', () => {
330:       if (buff) {
331:         add(buff, true);
332:       }
333:       if (options.order === 'desc') {
334:         results = results.reverse();
335:       }
