341:     function add(buff, attempt) {
342:       try {
343:         const log = JSON.parse(buff);
344:         if (check(log)) {
345:           push(log);
346:         }
347:       } catch (e) {
348:         if (!attempt) {
349:           stream.emit('error', e);
350:         }
351:       }
352:     }
353: 
354:     function push(log) {
355:       if (
356:         options.rows &&
357:         results.length >= options.rows &&
358:         options.order !== 'desc'
