383:         return;
384:       }
385: 
386:       if (typeof log !== 'object') {
387:         return;
388:       }
389: 
390:       const time = new Date(log.timestamp);
391:       if (
392:         (options.from && time < options.from) ||
393:         (options.until && time > options.until) ||
394:         (options.level && options.level !== log.level)
395:       ) {
396:         return;
397:       }
398: 
399:       return true;
400:     }
